private boolean unlink(ListNodeImpl<E> node){
    if (node == null || node.list == null) {
        return false;
    }
    // Detach the node from its neighbours
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // node was the list head
        node.list.head = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node was the list tail
        node.list.tail = node.prev;
    }
    // Null out the node's pointers and list reference
    node.prev = null;
    node.next = null;
    // Decrement the list size
    node.list.size--;
    node.list = null;
    return true;
}

