public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    // Ignore leading '/' if the path is absolute
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] segments = rawPath.split("/");
    for (String seg : segments) {
        if (seg.isEmpty()) {
            continue;
        }
        String value;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, fall back to the raw segment
                value = seg;
            }
        } else {
            value = seg;
        }
        result.add(new PathSegmentImpl(value));
    }
    return result;
}

