public String format(LoggingEvent event){
    if(event==null) return "";
    String pat = pattern!=null?pattern:"%d{HH:mm:ss} %-5p %c: %m%n";
    StringBuilder sb = new StringBuilder();
    int len = pat.length();
    for(int i=0;i<len;i++){
        char c = pat.charAt(i);
        if(c=='%' && i+1<len){
            char next = pat.charAt(i+1);
            switch(next){
                case 'm':
                    sb.append(event.getRenderedMessage());
                    i++;
                    break;
                case 'p':
                    sb.append(event.getLevel());
                    i++;
                    break;
                case 'c':
                    sb.append(event.getLoggerName());
                    i++;
                    break;
                case 'd':
                    int start = i+2;
                    if(start<len && pat.charAt(start)=='{'){
                        int end = pat.indexOf('}',start);
                        String fmt = (end>start)?pat.substring(start+1,end):"yyyy-MM-dd HH:mm:ss";
                        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(fmt,java.util.Locale.getDefault());
                        sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
                        if(end>start)i=end;
                    }else{
                        sb.append(new java.util.Date(event.getTimeStamp()));
                    }
                    i++;
                    break;
                case '%':
                    sb.append('%');
                    i++;
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    i++;
                    break;
                default:
                    sb.append(c);
                    break;
            }
        }else{
            sb.append(c);
        }
    }
    return sb.toString();
}

