public String format(final LoggingEvent event){
    // Build the formatted log entry using a StringBuilder
    StringBuilder sb = new StringBuilder();

    // Timestamp in ISO-like format
    sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
              .format(new java.util.Date(event.getTimeStamp())));

    // Thread name
    sb.append(" [").append(event.getThreadName()).append("] ");

    // Log level (left-justified to width 5)
    sb.append(String.format("%-5s", event.getLevel().toString()));

    // Logger name
    sb.append(" ").append(event.getLoggerName()).append(" - ");

    // Message (safe conversion from Object to String)
    Object messageObj = event.getMessage();
    sb.append(messageObj != null ? messageObj.toString() : "null");

    // New line to separate log entries
    sb.append(System.lineSeparator());

    return sb.toString();
}

