public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null) return;
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) return;

    // select the specified row
    table.setRowSelectionInterval(row, row);

    // make the row visible within the viewport
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        table.scrollRectToVisible(cellRect);
        if (pane != null) {
            JScrollBar horizontal = pane.getHorizontalScrollBar();
            JScrollBar vertical = pane.getVerticalScrollBar();
            if (horizontal != null) horizontal.setValue(cellRect.x);
            if (vertical != null) vertical.setValue(cellRect.y);
        }
    }

    // delay repaint to ensure the table paints the newly selected row
    SwingUtilities.invokeLater(() -> {
        if (pane != null) {
            pane.revalidate();
            pane.repaint();
        }
        table.revalidate();
        table.repaint();
    });
}

