        try {
            java.lang.reflect.Method method = channels.getClass().getMethod("register", IConsumer.class);
            method.invoke(channels, consumer);
        } catch (Exception ex) {
            throw new RuntimeException("Failed to add consumer to channels", ex);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to add consumer to channels", e);
    }
}

