public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("String index out of range");
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i += 2;
            continue;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

